package com.buildertoolbox.client;
import java.util.*;import net.fabricmc.fabric.api.client.event.lifecycle.v1.ClientTickEvents;import net.fabricmc.fabric.api.client.networking.v1.ClientPlayConnectionEvents;import net.fabricmc.fabric.api.client.rendering.v1.world.WorldRenderEvents;import net.minecraft.client.MinecraftClient;import net.minecraft.client.render.VertexRendering;import net.minecraft.client.render.RenderLayers;import net.minecraft.util.shape.VoxelShapes;import com.buildertoolbox.client.events.world.TickEvent;import com.buildertoolbox.client.events.render.Render3DEvent;
public final class StandaloneClient {private static List<Render3DEvent.Box> boxes=List.of();private static int ticks;
 public static void install(){ClientTickEvents.START_CLIENT_TICK.register(mc->ClientRuntime.EVENT_BUS.post(new TickEvent.Pre()));ClientTickEvents.END_CLIENT_TICK.register(mc->{ClientRuntime.EVENT_BUS.post(new TickEvent.Post());if(++ticks%200==0)Config.save();});ClientPlayConnectionEvents.DISCONNECT.register((handler,mc)->{ClientRuntime.EVENT_BUS.post(new com.buildertoolbox.client.events.game.GameLeftEvent());for(var m:com.buildertoolbox.client.systems.modules.Modules.get().getAll())m.disable();com.buildertoolbox.client.utils.player.Rotations.clear();Config.save();});WorldRenderEvents.END_EXTRACTION.register(context->{boxes=List.copyOf(ClientRuntime.EVENT_BUS.post(new Render3DEvent()).renderer.boxes);});WorldRenderEvents.BEFORE_DEBUG_RENDER.register(context->{var camera=context.worldState().cameraRenderState.pos;for(var box:boxes){var p=box.pos();VertexRendering.drawOutline(context.matrices(),context.consumers().getBuffer(RenderLayers.lines()),VoxelShapes.fullCube(),p.getX()-camera.x,p.getY()-camera.y,p.getZ()-camera.z,box.color(),1.0f);}});}
 public static boolean key(int key,int action){var event=ClientRuntime.EVENT_BUS.post(new com.buildertoolbox.client.events.meteor.KeyEvent(key,action));if(event.isCancelled())return true;var mc=MinecraftClient.getInstance();if(key==344&&action==1&&(mc.currentScreen==null||mc.currentScreen instanceof net.minecraft.client.gui.screen.TitleScreen)){mc.setScreen(new com.buildertoolbox.client.gui.screens.ToolboxScreen());return true;}return false;}
}